import { useEffect, useState } from "react";
import { CSS } from "../../../stitches.config";
import Text from "../Text/Text";
import type * as Stitches from "@stitches/react";
import { Flex } from "../Flex/Flex";

const convertNumberWithUnit = (value: string | number) => {
  let bigValue = BigInt(value);
  let number: number = 0;
  let unit: string = "Wei";

  if (bigValue < 10 ** 6) {
    number = Number(bigValue);
    unit = "Wei";
  } else if (bigValue >= 10 ** 6 && bigValue < 10 ** 9) {
    number = Number(bigValue) / 10 ** 6;
    unit = "Mwei";
  } else if (bigValue >= 10 ** 9 && bigValue < 10 ** 12) {
    number = Number(bigValue) / 10 ** 9;
    unit = "Gwei";
  } else if (bigValue >= 10 ** 12 && bigValue < 10 ** 15) {
    number = Number(bigValue) / 10 ** 12;
    unit = "Microether";
  } else if (bigValue >= 10 ** 15 && bigValue < 10 ** 18) {
    number = Number(bigValue) / 10 ** 15;
    unit = "Milliether";
  } else if (bigValue >= 10 ** 18) {
    number = Number(bigValue) / 10 ** 18;
    unit = "Ether";
  }

  return { number: number.toFixed(0), unit };
};

interface Props extends Stitches.VariantProps<typeof Text> {
  value: string | number;
  css?: CSS;
  numberCss?: CSS;
  unitCss?: CSS;
}

export const TextNumberWithUnit: React.FC<Props> = ({ value, ...props }) => {
  const { number, unit } = convertNumberWithUnit(value);

  return (
    <Flex css={{ gap: "$xs", alignItems: "center", ...props?.css }}>
      <Text css={{ ...props?.numberCss }}>{number}</Text>
      <Text css={{ ...props?.unitCss }}>{unit}</Text>
    </Flex>
  );
};
